// Generated by bildr from .bildr/modules/blog. Editing this file detaches it from the editor.
import { fileURLToPath } from 'node:url'
import { $fetch, fetch, setup } from '@nuxt/test-utils/e2e'
import { describe, expect, it } from 'vitest'

describe('blog API', async () => {
  await setup({
    rootDir: fileURLToPath(new URL('../../../..', import.meta.url)),
    env: { NUXT_DB_URL: `file:.data/test-${Date.now()}.db` }
  })

  it('creates, lists and publishes a post', async () => {
    const id = crypto.randomUUID()
    const created = await $fetch('/api/blog/posts', { method: 'POST', body: { id, title: 'From test', slug: 'from-test' } })
    expect(created).toMatchObject({ id, published: false })

    const page = await $fetch<{ items: Array<{ id: string }>, total: number }>('/api/blog/posts')
    expect(page.items.map(post => post.id)).toContain(id)

    const published = await $fetch(`/api/blog/posts/${id}/publish`, { method: 'POST' })
    expect(published).toMatchObject({ id, published: true })
  })

  it('maps domain errors to HTTP statuses', async () => {
    const body = { id: crypto.randomUUID(), title: 'Dup', slug: 'dup' }
    await $fetch('/api/blog/posts', { method: 'POST', body })
    const response = await fetch('/api/blog/posts', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ...body, id: crypto.randomUUID() })
    })
    expect(response.status).toBe(409)
  })

  it('rejects invalid input with 400', async () => {
    const response = await fetch('/api/blog/posts', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ title: '' })
    })
    expect(response.status).toBe(400)
  })

  it('serves the SPA shell', async () => {
    const html = await $fetch<string>('/')
    expect(html).toMatch(/<div id="__nuxt"[ >]/)
    expect(html).toContain('data-ssr="false"')
  })
})
